/* Declared design examples. This is not a learned failure classifier or robot trainer. */
function improvementStats(row){
 for(const k of ['entered','passed','failed','unknown','notAttempted'])if(!Number.isInteger(row[k])||row[k]<0)throw Error('Invalid stage count: '+k);
 if(row.passed+row.failed+row.unknown!==row.entered)throw Error('Stage outcomes must account for every entry');
 const known=row.passed+row.failed;
 return {known,rate:known?row.passed/known:null,coverage:row.entered?known/row.entered:null,lower:row.entered?row.passed/row.entered:null,upper:row.entered?(row.passed+row.unknown)/row.entered:null};
}
function validateImprovementCase(c,stages){
 if(!Number.isInteger(c.episodes)||c.episodes<=0||!Number.isInteger(c.fullTaskSuccess)||c.fullTaskSuccess<0||c.fullTaskSuccess>c.episodes)throw Error('Invalid task count');
 if(c.rows.length!==stages.length)throw Error('Missing stage');
 c.rows.forEach((r,i)=>{improvementStats(r);if(r.stageId!==stages[i].id||r.entered+r.notAttempted!==c.episodes)throw Error('Invalid stage accounting');if(i&&r.entered>c.rows[i-1].passed+c.rows[i-1].unknown)throw Error('Later stage cannot be reached before prior stage');});
 if(c.fullTaskSuccess>c.rows.at(-1).passed+c.rows.at(-1).unknown)throw Error('Task success exceeds final-stage evidence');
 if(!stages.some(s=>s.id===c.targetStage)||!['correction','probe','bootstrap','observe'].includes(c.route))throw Error('Invalid plan example');
 return true;
}
function improvementDecision(c,health){
 if(health==='repair')return {kind:'repair',label:'Sửa hệ thống và lập baseline mới',steps:['Kiểm và sửa camera, tọa độ hoặc điều khiển theo lỗi đã xác nhận.','Pin binding/scorer/version mới, đánh giá lại baseline.','Chưa tính sửa hệ thống là lợi ích của thêm dữ liệu.'],training:['Chưa mở gói học từ lỗi hệ thống.','Nếu task ngoài khả năng bộ gắp/vùng với tới, thu hẹp task.','Ghi toàn bộ công sửa và các lượt thử lại.']};
 const labels={correction:'Thu correction có chủ đích',probe:'Kiểm bước trước rồi chọn vùng cần học',bootstrap:'Kiểm khả thi và tạo kỹ năng nền',observe:'Bổ sung dấu hiệu chấm trước khi chọn cách học'};
 return {kind:c.route,label:labels[c.route],steps:c.plan,training:c.training};
}
function taskImprovementMarkup(){return `<section class="task-improvement" id="task-improvement" aria-labelledby="improvement-title"><header><span class="opening-kicker">PHẦN CỐT LÕI CỦA SOLUTION</span><h2 id="improvement-title">Biết robot sai ở đâu.<br>Kiểm xem cần học từ chỗ nào.</h2><p>Một lỗi quan sát được mở ra phép kiểm và kế hoạch cải thiện. Kỹ sư duyệt; hệ thống giữ cả trường hợp chưa biết hoặc chưa cải thiện.</p><span class="improvement-example-label">Các số bên dưới là ví dụ được dựng · Chưa là số đo robot</span></header><div class="improvement-tabs" role="group" aria-label="Chọn ví dụ cải thiện">${TASK_IMPROVEMENT.cases.map((c,i)=>`<button type="button" data-improvement-case="${c.id}" aria-pressed="${i===0}"><span>0${i+1}</span>${esc(c.label)}</button>`).join('')}</div><div class="improvement-flow" aria-label="Luồng cải thiện"><span>Chấm từng bước</span><i>→</i><span>Kiểm hệ thống / nguyên nhân</span><i>→</i><span>Correction hoặc kỹ năng nền</span><i>→</i><span>Học & kiểm cả task</span></div><div class="improvement-body"></div><details class="improvement-contracts"><summary>Cách biết một bước đã làm đúng?</summary><div>${TASK_IMPROVEMENT.stages.map(s=>`<article><strong>${s.label}</strong><p>${s.criterion}</p></article>`).join('')}</div><p>Người phụ trách task chốt tiêu chuẩn và bộ chấm. Simulation có state để kiểm; robot thật cần sensor hoặc nhãn người phù hợp. Đóng gripper đơn thuần chưa đủ chứng minh đã giữ vật.</p></details><footer><a href="#learning">Cơ chế học và kế hoạch cập nhật →</a><a href="#validation">Phép kiểm và giới hạn →</a><a href="#resources">Đọc đặc tả 14 và audit đầy đủ →</a></footer></section>`;}
function improvementBody(c,stageId,health){const selected=c.rows.find(r=>r.stageId===stageId),s=TASK_IMPROVEMENT.stages.find(s=>s.id===stageId),stats=improvementStats(selected),plan=improvementDecision(c,health),pct=x=>x===null?'Chưa xác định':Math.round(x*100)+'%';return `<div class="improvement-case-intro"><div><h3>${esc(c.summary)}</h3><p>Ví dụ ${c.episodes} lượt từ đầu task · ${c.fullTaskSuccess} lượt hoàn thành · Một attempt mỗi bước/lượt, không có retry trong ví dụ.</p></div><span class="improvement-task-score">${c.fullTaskSuccess}/${c.episodes}<small>Toàn task · Ví dụ</small></span></div><div class="improvement-grid"><section class="improvement-stage-report"><h3>01 · Bước nào thực sự được thử?</h3><p class="improvement-hint">Nhấn một bước để xem tiêu chuẩn và mẫu số.</p><div class="improvement-legend"><span>● Đúng</span><span>● Sai</span><span>● Chưa rõ</span><span>○ Chưa thử</span></div>${c.rows.map((r,i)=>{const k=improvementStats(r);return `<button type="button" class="improvement-stage-row" data-improvement-stage="${r.stageId}" aria-pressed="${stageId===r.stageId}"><span class="improvement-stage-name">${TASK_IMPROVEMENT.stages[i].label}<small>${r.entered} lượt tới bước · ${r.notAttempted} chưa thử</small></span><span class="improvement-stage-bar" aria-hidden="true"><i style="width:${r.passed/c.episodes*100}%"></i><i style="width:${r.failed/c.episodes*100}%"></i><i style="width:${r.unknown/c.episodes*100}%"></i></span><span class="improvement-stage-rate">${pct(k.rate)}<small>${r.passed} đúng / ${k.known} đã chấm</small></span></button>`;}).join('')}<div class="improvement-selected-stage"><strong>${s.label}: ${pct(stats.rate)} trên số đã chấm</strong><p>${s.criterion}</p><p>${selected.passed} đúng · ${selected.failed} sai · ${selected.unknown} chưa rõ · ${selected.notAttempted} chưa thử. Độ phủ chấm ${pct(stats.coverage)} trên ${selected.entered} lượt tới bước.${selected.unknown?` Khoảng khả dĩ ${pct(stats.lower)}–${pct(stats.upper)}; chưa đủ để xếp điểm nghẽn chắc chắn.`:''}</p></div><p class="improvement-boundary">${esc(c.limit)}</p></section><section class="improvement-probe"><h3>02 · Kiểm nguyên nhân trước</h3><strong>${esc(c.probe.question)}</strong><p>${esc(c.probe.test)}</p><div class="improvement-probe-example"><span>${c.probe.status==='scripted_probe'?'KẾT QUẢ PROBE ĐƯỢC DỰNG':'PHÉP KIỂM CẦN THỰC HIỆN'}</span><p>${esc(c.probe.example)}</p></div><fieldset class="improvement-health"><legend>Thử nhánh xử lý sau kiểm hệ thống</legend><button type="button" data-improvement-health="clear" aria-pressed="${health==='clear'}">Xét kỹ năng / dữ liệu</button><button type="button" data-improvement-health="repair" aria-pressed="${health==='repair'}">Có lỗi hệ thống</button></fieldset><p class="improvement-hint">Đã kiểm hệ thống vẫn cần bằng chứng cho giả thuyết dữ liệu.</p></section></div><div class="improvement-plan-grid"><section><span>03 · KẾ HOẠCH THU / CAN THIỆP</span><h3>${esc(plan.label)}</h3><ol>${plan.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section><section><span>04 · KẾ HOẠCH HỌC & KIỂM</span><h3>${plan.kind==='repair'||plan.kind==='observe'?'Chưa mở huấn luyện':'Cập nhật từ đâu, giữ lại gì?'}</h3><ol>${plan.training.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section></div><div class="improvement-checks"><strong>Điều kiện để nhận cải thiện</strong><p>Đo bước yếu + chuyển tiếp + toàn task từ trạng thái tự nhiên + các điều kiện đang tốt. Giữ cả no-gain; chốt mô hình rồi kiểm giữ riêng. Tính công chấm, probe, reset, thu, QA, học và đo lại.</p></div>`;}
function initTaskImprovement(signal){const host=document.querySelector('.task-improvement');if(!host)return;TASK_IMPROVEMENT.cases.forEach(c=>validateImprovementCase(c,TASK_IMPROVEMENT.stages));let caseId='grasp',stageId='grasp',health='clear';function render(){const c=TASK_IMPROVEMENT.cases.find(c=>c.id===caseId);host.querySelector('.improvement-body').innerHTML=improvementBody(c,stageId,health);host.querySelectorAll('[data-improvement-case]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.improvementCase===caseId)));}
 host.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.improvementCase){caseId=b.dataset.improvementCase;stageId=TASK_IMPROVEMENT.cases.find(c=>c.id===caseId).targetStage;health='clear';render();}else if(b.dataset.improvementStage){stageId=b.dataset.improvementStage;render();}else if(b.dataset.improvementHealth){health=b.dataset.improvementHealth;render();}},{signal});render();}
if(typeof module!=='undefined')module.exports={improvementStats,validateImprovementCase,improvementDecision};
